#include <iostream>
#include <queue>
#include <sstream>
#include <string>
#include <vector>

// The solution file defines this struct identically; the layout must match.
struct TreeNode
{
    int val;
    TreeNode* left;
    TreeNode* right;
};

bool IsValidBst(const TreeNode* root);

static void destroy(TreeNode* n)
{
    if (!n) { return; }
    destroy(n->left);
    destroy(n->right);
    delete n;
}

// Level-order, "null" for a missing child: "5 1 7 null null 4 8".
static TreeNode* build(const std::vector<std::string>& tok)
{
    if (tok.empty() || tok[0] == "null") { return nullptr; }
    TreeNode* root = new TreeNode{std::stoi(tok[0]), nullptr, nullptr};
    std::queue<TreeNode*> q;
    q.push(root);
    std::size_t i = 1;
    while (!q.empty() && i < tok.size())
    {
        TreeNode* n = q.front();
        q.pop();
        if (i < tok.size() && tok[i] != "null")
        {
            n->left = new TreeNode{std::stoi(tok[i]), nullptr, nullptr};
            q.push(n->left);
        }
        i++;
        if (i < tok.size() && tok[i] != "null")
        {
            n->right = new TreeNode{std::stoi(tok[i]), nullptr, nullptr};
            q.push(n->right);
        }
        i++;
    }
    return root;
}

int main()
{
    std::string line;
    while (std::getline(std::cin, line))
    {
        std::istringstream in(line);
        std::vector<std::string> tok;
        std::string t;
        while (in >> t) { tok.push_back(t); }
        TreeNode* root = build(tok);
        std::cout << (IsValidBst(root) ? "true" : "false") << "\n";
        destroy(root);
    }
    return 0;
}

