"""Random trees in level-order form. Half are real BSTs built by inserting
distinct values; the rest have one value corrupted so the tree is
(usually) invalid, including cases that look fine locally."""


def _insert(node, v):
    if node is None:
        return {"v": v, "l": None, "r": None}
    if v < node["v"]:
        node["l"] = _insert(node["l"], v)
    else:
        node["r"] = _insert(node["r"], v)
    return node


def _nodes(node, out):
    if node:
        out.append(node)
        _nodes(node["l"], out)
        _nodes(node["r"], out)
    return out


def _serialise(root):
    if root is None:
        return "null"
    out, queue = [], [root]
    while queue:
        n = queue.pop(0)
        if n is None:
            out.append("null")
            continue
        out.append(str(n["v"]))
        queue.append(n["l"])
        queue.append(n["r"])
    while out and out[-1] == "null":
        out.pop()
    return " ".join(out)


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    values = rng.sample(range(-20, 40), rng.randint(1, 10))
    root = None
    for v in values:
        root = _insert(root, v)
    corrupted = rng.random() < 0.5
    if corrupted:
        node = rng.choice(_nodes(root, []))
        node["v"] = rng.choice(values)  # often a duplicate or an ancestor clash
    return {"name": "a %d-node tree%s #%d" % (len(values),
                                               " with one value changed" if corrupted else "",
                                               index),
            "stdin": _serialise(root) + "\n"}
